// Function to update the chess game label
function updateGameLabel() {
    const movesSequence = game.getHistory().slice(0, 20);

    mvsCondition(2)
    .then(() => {
        statisticsButton()

        gameLabel.innerText = 'Chess game label: ';

        movesSequence.forEach((move, index) => {
            gameLabel.innerText += ` Move ${index + 1}: ${move.square()}\n`;
        });
    });
}

// Function to update the chess moves container
function updateMoveContainer() {
    gameLabel.innerText = 'chessBoardMoves:';

    const from = fromInput.value.toLowerCase();
    const to = toInput.value.toLowerCase();

    // Check if moves are legal and update the container
    game.getLegalMoves()
        .then(legalMoves => {
            const move = [from, to];
            if (legalMoves.includes(move)) {
                movesContainer.innerText = legalMoves.join(', ');
            }
            else {
                movesContainer.innerText = 'Invalid move';
            }
        })
        .catch(error => console.error(error));
}

// Function to update the chess moves container
function updateStartButton() {
    startButton.disabled = (fromInput.value.length === 0 || toInput.value.length === 0);
}

// Event listener for the game label update button
statisticButton.addEventListener('click', updateGameLabel);

// Event listener for the from and to input fields to update the start button state
fromInput.addEventListener('input', updateStartButton);
toInput.addEventListener('input', updateStartButton);

// Event listener for the start button to start the chess game
startButton.addEventListener('click', () => {
    fromInput.disabled = true;
    toInput.disabled = true;
    startButton.disabled = true;

    // Start the timer
    startButton.disabled = true;
    startButton.disabled = true;
});

